#!/usr/bin/env python3
from pathlib import Path

# Build66: simplify the field wizard around the actual failure boundary.
# Keep the proven deep diagnostics below, but make the main flow sequential:
# AI config/connectivity -> TTS -> one full GigaAM voice turn -> steering parity.

# ---------------------------------------------------------------------------
# Bridge: expose a sanitized multi-provider snapshot and generic custom setup.
# ---------------------------------------------------------------------------
p = Path('app/src/main/kotlin/com/bydmate/app/ui/diagnostics/DiLink3E2EBridge.kt')
s = p.read_text()
anchor = '    suspend fun productionSnapshot(): ProductionSnapshot {\n'
if anchor not in s:
    raise SystemExit('Build66: productionSnapshot anchor not found')
if 'data class Build66AgentConfig(' not in s:
    insert = '''    data class Build66AgentConfig(\n        val enabled: Boolean,\n        val requestedProvider: String,\n        val resolvedProvider: String,\n        val customName: String,\n        val customBaseUrl: String,\n        val customApiKey: String,\n        val customModel: String,\n        val openRouterConfigured: Boolean,\n        val openRouterModel: String,\n        val zaiConfigured: Boolean,\n    )\n\n    suspend fun build66AgentConfig(): Build66AgentConfig {\n        val repo = deps.settingsRepository()\n        val enabled = repo.getString(SettingsRepository.KEY_AGENT_ENABLED, "false").toBoolean()\n        val requested = repo.getString(SettingsRepository.KEY_AGENT_PRIMARY_CONN, "")\n        val customName = repo.getString(SettingsRepository.KEY_CUSTOM_NAME, "")\n        val customBase = repo.getString(SettingsRepository.KEY_CUSTOM_BASE_URL, "").trim().trimEnd('/')\n        val customKey = repo.getString(SettingsRepository.KEY_CUSTOM_API_KEY, "")\n        val customModel = repo.getString(SettingsRepository.KEY_CUSTOM_MODEL, "")\n        val customOk = customBase.isNotBlank() && customKey.isNotBlank() && customModel.isNotBlank()\n        val openModel = repo.getString(SettingsRepository.KEY_OPENROUTER_MODEL, "")\n        val openOk = repo.getString(SettingsRepository.KEY_OPENROUTER_API_KEY, "").isNotBlank() && openModel.isNotBlank()\n        val zaiOk = repo.getString(SettingsRepository.KEY_ZAI_API_KEY, "").isNotBlank()\n        val resolved = when {\n            requested == "custom" && customOk -> "custom"\n            requested == "openrouter" && openOk -> "openrouter"\n            requested == "zai" && zaiOk -> "zai"\n            openOk -> "openrouter"\n            zaiOk -> "zai"\n            customOk -> "custom"\n            else -> ""\n        }\n        DiLink3DebugLog.log(\n            appContext,\n            "BUILD66_AI_CONFIG",\n            "package=${appContext.packageName} enabled=$enabled requested=$requested resolved=$resolved " +\n                "customName=$customName customBase=$customBase customModel=$customModel customKeyPresent=${customKey.isNotBlank()} " +\n                "openrouterConfigured=$openOk openrouterModel=$openModel zaiConfigured=$zaiOk"\n        )\n        return Build66AgentConfig(\n            enabled = enabled,\n            requestedProvider = requested,\n            resolvedProvider = resolved,\n            customName = customName,\n            customBaseUrl = customBase,\n            customApiKey = customKey,\n            customModel = customModel,\n            openRouterConfigured = openOk,\n            openRouterModel = openModel,\n            zaiConfigured = zaiOk,\n        )\n    }\n\n    suspend fun saveBuild66CustomConnection(name: String, baseUrl: String, apiKey: String, model: String) {\n        val url = baseUrl.trim().trimEnd('/')\n        val key = apiKey.trim()\n        val chosenModel = model.trim()\n        require(url.isNotBlank()) { "Base URL пустой" }\n        require(key.isNotBlank()) { "API key пустой" }\n        require(chosenModel.isNotBlank()) { "Model пустой" }\n        deps.settingsRepository().setStrings(\n            mapOf(\n                SettingsRepository.KEY_CUSTOM_NAME to name.trim().ifBlank { "AI Hub" },\n                SettingsRepository.KEY_CUSTOM_BASE_URL to url,\n                SettingsRepository.KEY_CUSTOM_API_KEY to key,\n                SettingsRepository.KEY_CUSTOM_MODEL to chosenModel,\n                SettingsRepository.KEY_AGENT_PRIMARY_CONN to "custom",\n                SettingsRepository.KEY_AGENT_ENABLED to "true",\n            )\n        )\n        DiLink3DebugLog.log(appContext, "BUILD66_AI_CONFIG_SAVED", "name=${name.trim()} baseUrl=$url model=$chosenModel keyPresent=true")\n    }\n\n'''
    s = s.replace(anchor, insert + anchor, 1)
p.write_text(s)

# ---------------------------------------------------------------------------
# Main wizard state + automatic refresh while the diagnostic panel is visible.
# ---------------------------------------------------------------------------
p = Path('app/src/main/kotlin/com/bydmate/app/ui/diagnostics/DiLink3VoiceDebugPanel.kt')
s = p.read_text()
state_anchor = '    var build65TtsPassed by remember { mutableStateOf(false) }\n'
if state_anchor not in s:
    raise SystemExit('Build66: Build65 state anchor not found')
if 'var build66Config by remember' not in s:
    state = '''    var build66Config by remember { mutableStateOf<DiLink3E2EBridge.Build66AgentConfig?>(null) }\n    var build66Name by remember { mutableStateOf("AI Hub") }\n    var build66BaseUrl by remember { mutableStateOf(DiLink3E2EBridge.AIHUBMIX_BASE_URL) }\n    var build66ApiKey by remember { mutableStateOf("") }\n    var build66Model by remember { mutableStateOf(DiLink3E2EBridge.DEFAULT_AIHUBMIX_MODEL) }\n    var build66AiStatus by remember { mutableStateOf("checking configuration...") }\n    var build66AiAnswer by remember { mutableStateOf("") }\n    var build66UiTick by remember { mutableStateOf(0) }\n    LaunchedEffect(Unit) {\n        val cfg = runCatching { build65Bridge.build66AgentConfig() }.getOrNull()\n        build66Config = cfg\n        if (cfg != null) {\n            build66Name = cfg.customName.ifBlank { "AI Hub" }\n            build66BaseUrl = cfg.customBaseUrl.ifBlank { DiLink3E2EBridge.AIHUBMIX_BASE_URL }\n            build66ApiKey = cfg.customApiKey\n            build66Model = cfg.customModel.ifBlank { DiLink3E2EBridge.DEFAULT_AIHUBMIX_MODEL }\n            if (!cfg.enabled) {\n                build66AiStatus = "FAIL - агент выключен в этой диагностической установке"\n            } else if (cfg.resolvedProvider.isBlank()) {\n                build66AiStatus = "FAIL - нет полного URL + API key + model"\n            } else {\n                build66AiStatus = "testing ${cfg.resolvedProvider}..."\n                val r = build65Bridge.askOnly("Ответь одним коротким словом: готово")\n                if (r.error != null) build66AiStatus = "FAIL: ${r.error}"\n                else { build66AiStatus = "PASS - ${cfg.resolvedProvider}"; build66AiAnswer = r.answer.orEmpty() }\n            }\n        } else {\n            build66AiStatus = "FAIL - не удалось прочитать настройки агента"\n        }\n    }\n    LaunchedEffect(Unit) {\n        while (true) {\n            kotlinx.coroutines.delay(750L)\n            build66UiTick++\n        }\n    }\n'''
    s = s.replace(state_anchor, state_anchor + state, 1)

# Replace Build65's top wizard AND the legacy Build64 screen-PTT duplicate with one clean flow.
start_marker = '            Text("DiLink3 Build65 PRODUCTION WIZARD", style = MaterialTheme.typography.titleLarge)\n'
start = s.find(start_marker)
if start < 0:
    raise SystemExit('Build66: Build65 wizard start not found')
legacy_text = s.find('                "Эта кнопка запускает тот же VoiceController PTT путь', start)
if legacy_text < 0:
    raise SystemExit('Build66: legacy Build64 duplicate explanation not found')
end = s.find('            )\n\n', legacy_text)
if end < 0:
    raise SystemExit('Build66: legacy Build64 duplicate end not found')
end += len('            )\n\n')

block = '''            Text("DiLink3 Build66 - ПОШАГОВАЯ ДИАГНОСТИКА", style = MaterialTheme.typography.titleLarge)\n\n            val b65 = context.getSharedPreferences("build65_prod_wizard", Context.MODE_PRIVATE)\n            val b61 = context.getSharedPreferences("build61_voice_trace", Context.MODE_PRIVATE)\n            val build66Tick = build66UiTick\n            val pttSource = b65.getString("last_ptt_source", "").orEmpty()\n            val pcmOk = b65.getBoolean("pcm_seen", false)\n            val speechOk = b65.getBoolean("speech_seen", false)\n            val utteranceOk = b65.getBoolean("utterance_seen", false)\n            val utteranceText = b65.getString("utterance_text", "").orEmpty()\n            val agentError = b65.getString("agent_error", "").orEmpty()\n            val assistantText = b61.getString("last_assistant", "").orEmpty()\n            val steeringOk = com.bydmate.app.cluster.SteeringWheelKeyService.isConnected\n            val cfg66 = build66Config\n            val aiConfigured = cfg66?.resolvedProvider?.isNotBlank() == true\n            val aiReady = cfg66?.enabled == true && aiConfigured && build66AiStatus.startsWith("PASS")\n            val voiceChainOk = pcmOk && speechOk && utteranceOk && agentError.isBlank() && assistantText.isNotBlank()\n\n            Text("ШАГ 1 - AI / API", style = MaterialTheme.typography.titleMedium)\n            Text(\n                "Build66 установлен как отдельный пакет ${context.packageName}. Настройки обычного BYDMate не переносятся автоматически. Здесь сразу видно, есть ли LLM-конфигурация именно у этой диагностической сборки.",\n                style = MaterialTheme.typography.bodySmall,\n            )\n            DebugRow("Agent enabled", cfg66?.let { if (it.enabled) "PASS" else "FAIL - выключен" } ?: "checking...")\n            DebugRow("Requested provider", cfg66?.requestedProvider?.ifBlank { "<не выбран>" } ?: "checking...")\n            DebugRow("Resolved provider", cfg66?.resolvedProvider?.ifBlank { "FAIL - ни один не настроен" } ?: "checking...")\n            DebugRow("OpenRouter", cfg66?.let { if (it.openRouterConfigured) "configured / ${it.openRouterModel}" else "not configured" } ?: "checking...")\n            DebugRow("z.ai", cfg66?.let { if (it.zaiConfigured) "configured" else "not configured" } ?: "checking...")\n            DebugRow("Custom name", cfg66?.customName?.ifBlank { "<empty>" } ?: "checking...")\n            DebugRow("Custom URL", cfg66?.customBaseUrl?.ifBlank { "<empty>" } ?: "checking...")\n            DebugRow("Custom model", cfg66?.customModel?.ifBlank { "<empty>" } ?: "checking...")\n            DebugRow("Custom API key", cfg66?.let { if (it.customApiKey.isNotBlank()) "present" else "MISSING" } ?: "checking...")\n            DebugRow("REAL AI TEST", build66AiStatus)\n            DebugRow("AI answer", build66AiAnswer.ifBlank { "<none>" })\n\n            Text("Настроить AI Hub / любой OpenAI-compatible API прямо здесь:", style = MaterialTheme.typography.bodySmall)\n            OutlinedTextField(\n                value = build66Name,\n                onValueChange = { build66Name = it },\n                label = { Text("Название (например AI Hub)") },\n                singleLine = true,\n                modifier = Modifier.fillMaxWidth(),\n            )\n            OutlinedTextField(\n                value = build66BaseUrl,\n                onValueChange = { build66BaseUrl = it },\n                label = { Text("Base URL") },\n                supportingText = { Text("AIHubMix: https://aihubmix.com/v1") },\n                singleLine = true,\n                modifier = Modifier.fillMaxWidth(),\n            )\n            OutlinedTextField(\n                value = build66ApiKey,\n                onValueChange = { build66ApiKey = it },\n                label = { Text("API key") },\n                singleLine = true,\n                visualTransformation = PasswordVisualTransformation(),\n                modifier = Modifier.fillMaxWidth(),\n            )\n            OutlinedTextField(\n                value = build66Model,\n                onValueChange = { build66Model = it },\n                label = { Text("Model") },\n                singleLine = true,\n                modifier = Modifier.fillMaxWidth(),\n            )\n            Button(\n                enabled = build66BaseUrl.isNotBlank() && build66ApiKey.isNotBlank() && build66Model.isNotBlank(),\n                onClick = {\n                    build66AiStatus = "saving + testing..."\n                    build66AiAnswer = ""\n                    scope.launch {\n                        try {\n                            build65Bridge.saveBuild66CustomConnection(build66Name, build66BaseUrl, build66ApiKey, build66Model)\n                            val cfg = build65Bridge.build66AgentConfig()\n                            build66Config = cfg\n                            val r = build65Bridge.askOnly("Ответь одним коротким словом: готово")\n                            if (r.error != null) build66AiStatus = "FAIL: ${r.error}"\n                            else { build66AiStatus = "PASS - ${cfg.resolvedProvider}"; build66AiAnswer = r.answer.orEmpty() }\n                        } catch (t: Throwable) {\n                            build66AiStatus = "FAIL: ${t::class.java.simpleName}: ${t.message}"\n                        }\n                    }\n                },\n                modifier = Modifier.fillMaxWidth(),\n            ) { Text("СОХРАНИТЬ И ПРОВЕРИТЬ AI") }\n            Button(\n                enabled = cfg66?.enabled == true && aiConfigured,\n                onClick = {\n                    build66AiStatus = "testing..."\n                    build66AiAnswer = ""\n                    scope.launch {\n                        val r = build65Bridge.askOnly("Ответь одним коротким словом: готово")\n                        if (r.error != null) build66AiStatus = "FAIL: ${r.error}"\n                        else { build66AiStatus = "PASS - ${build66Config?.resolvedProvider.orEmpty()}"; build66AiAnswer = r.answer.orEmpty() }\n                    }\n                },\n                modifier = Modifier.fillMaxWidth(),\n            ) { Text("ПОВТОРИТЬ ПРОВЕРКУ AI") }\n\n            Text("ШАГ 2 - ГРОМКОСТЬ / TTS", style = MaterialTheme.typography.titleMedium)\n            Button(\n                enabled = ttsEnabled && ttsReady,\n                onClick = {\n                    build65TtsStatus = "testing..."\n                    build65TtsPassed = false\n                    scope.launch {\n                        val r = build65Bridge.testTtsOnly()\n                        build65TtsPassed = r.error == null\n                        build65TtsStatus = if (r.error == null) "PASS - звук принят, gain x1.50" else "FAIL: ${r.error}"\n                    }\n                },\n                modifier = Modifier.fillMaxWidth(),\n            ) { Text("ПРОИГРАТЬ ТЕСТ ГРОМКОСТИ") }\n            DebugRow("TTS result", build65TtsStatus)\n\n            Text("ШАГ 3 - ПОЛНАЯ ГОЛОСОВАЯ ЦЕПОЧКА", style = MaterialTheme.typography.titleMedium)\n            Text("Одна кнопка проверяет сразу beep -> микрофон -> PCM -> речь -> GigaAM -> routing -> AI -> ответ. Отдельной дублирующей кнопки запуска PTT больше нет.", style = MaterialTheme.typography.bodySmall)\n            Button(\n                enabled = !voiceController.sessionActive(),\n                onClick = {\n                    DiLink3DebugLog.log(context, "BUILD66_FULL_VOICE_BUTTON", "action=press aiReady=$aiReady")\n                    b61.edit().remove("last_assistant").remove("last_assistant_source").apply()\n                    voiceController.build64PttFrom("build66_wizard_screen")\n                },\n                modifier = Modifier.fillMaxWidth(),\n            ) { Text("ЗАПУСТИТЬ ГОЛОСОВУЮ КОМАНДУ С ЭКРАНА") }\n            DebugRow("PTT source", pttSource.ifBlank { "<waiting>" })\n            DebugRow("1. Microphone / PCM", if (pcmOk) "PASS" else "waiting")\n            DebugRow("2. Speech detected", if (speechOk) "PASS" else "waiting")\n            DebugRow("3. GigaAM transcript", if (utteranceOk) "PASS - $utteranceText" else "waiting")\n            DebugRow("4. AI route", when { agentError.isNotBlank() -> "FAIL - $agentError"; assistantText.isNotBlank() -> "PASS"; utteranceOk -> "waiting for AI"; else -> "waiting" })\n            DebugRow("5. Assistant answer", assistantText.ifBlank { "<waiting>" })\n            DebugRow("FULL VOICE RESULT", if (voiceChainOk) "PASS" else if (agentError.isNotBlank()) "FAIL AT AI/API" else "waiting")\n\n            Text("ШАГ 4 - КНОПКА МИКРОФОНА НА РУЛЕ", style = MaterialTheme.typography.titleMedium)\n            Text("Ничего дополнительно нажимать на экране не нужно. Нажми физическую кнопку микрофона один раз и скажи команду. Строки ниже обновляются автоматически.", style = MaterialTheme.typography.bodySmall)\n            DebugRow("Steering service", if (steeringOk) "PASS" else "FAIL")\n            DebugRow("Last PTT source", pttSource.ifBlank { "<waiting>" })\n            DebugRow("Last recognized", utteranceText.ifBlank { "<waiting>" })\n            DebugRow("Last AI error", agentError.ifBlank { "none" })\n            DebugRow("Last assistant", assistantText.ifBlank { "<waiting>" })\n\n            Text("РАСШИРЕННАЯ ДИАГНОСТИКА", style = MaterialTheme.typography.titleMedium)\n            Text("Ниже оставлены старые низкоуровневые тесты и журналы только на случай, если один из четырёх шагов выше покажет конкретный FAIL.", style = MaterialTheme.typography.bodySmall)\n\n'''

s = s[:start] + block + s[end:]

# The old AIHubMix quick-setup card is now redundant with Build66 Step 1. Remove only that card;
# keep the old System-ASR E2E test below as an advanced fallback diagnostic.
legacy_ai_start = s.find('                Text("AI PROVIDER - AIHubMix", style = MaterialTheme.typography.titleSmall)')
legacy_e2e = s.find('                Text("STEP 2A - END TO END: System ASR -> BYDMate AI -> TTS", style = MaterialTheme.typography.titleSmall)', legacy_ai_start)
if legacy_ai_start >= 0 and legacy_e2e > legacy_ai_start:
    s = s[:legacy_ai_start] + s[legacy_e2e:]

p.write_text(s)
print('Build66 installed: compact step wizard + in-place AI config + automatic status + single full voice button')
